/** Small additive surfaces around the Harness-owned conversation UI. */
export declare const CHATROOM_STYLES = "\n.dsh-chatroom-launcher {\n  pointer-events: auto;\n  position: fixed;\n  right: 28px;\n  bottom: 28px;\n  z-index: 40;\n  border: 1px solid var(--border-primary, #e5e7eb);\n  border-radius: 999px;\n  background: var(--bg-primary, #fff);\n  color: var(--text-primary, #111827);\n  padding: 12px 20px;\n  font: inherit;\n  font-weight: 600;\n  box-shadow: 0 10px 30px rgb(0 0 0 / 10%);\n  cursor: pointer;\n}\n\n.dsh-chatroom-dialog-layer {\n  pointer-events: auto;\n  position: fixed;\n  inset: 0;\n  z-index: 60;\n  display: grid;\n  place-items: center;\n  padding: 24px;\n  background: rgb(0 0 0 / 28%);\n  backdrop-filter: blur(2px);\n}\n\n.dsh-chatroom-card {\n  position: relative;\n  width: min(420px, calc(100vw - 48px));\n  border: 1px solid var(--border-primary, #e5e7eb);\n  border-radius: 18px;\n  background: var(--bg-primary, #fff);\n  color: var(--text-primary, #111827);\n  padding: 28px;\n  box-shadow: 0 24px 70px rgb(0 0 0 / 18%);\n}\n\n.dsh-chatroom-card h2 { margin: 0 0 10px; font-size: 22px; }\n.dsh-chatroom-card p { margin: 0 0 20px; color: var(--text-secondary, #6b7280); line-height: 1.6; }\n\n.dsh-chatroom-close {\n  position: absolute;\n  top: 12px;\n  right: 14px;\n  border: 0;\n  background: transparent;\n  color: var(--text-secondary, #6b7280);\n  font: inherit;\n  font-size: 24px;\n  cursor: pointer;\n}\n\n.dsh-chatroom-name {\n  box-sizing: border-box;\n  width: 100%;\n  border: 1px solid var(--border-primary, #d1d5db);\n  border-radius: 10px;\n  background: var(--bg-primary, #fff);\n  color: var(--text-primary, #111827);\n  padding: 11px 13px;\n  font: inherit;\n  outline: none;\n}\n\n.dsh-chatroom-name:focus { border-color: var(--brand-primary, #4f7cff); }\n\n.dsh-chatroom-button {\n  width: 100%;\n  margin-top: 14px;\n  border: 0;\n  border-radius: 10px;\n  background: var(--brand-primary, #4f7cff);\n  color: #fff;\n  padding: 11px 16px;\n  font: inherit;\n  font-weight: 600;\n  cursor: pointer;\n}\n\n.dsh-chatroom-button:disabled { cursor: not-allowed; opacity: .45; }\n.dsh-chatroom-error { margin-top: 12px; color: #d14343; font-size: 13px; }\n\n.dsh-chatroom-identity-action {\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n  border: 0;\n  background: transparent;\n  color: var(--text-secondary, #6b7280);\n  padding: 4px 6px;\n  font: inherit;\n  font-size: 13px;\n  cursor: pointer;\n}\n\n.dsh-chatroom-presence-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: #a0a7b2;\n}\n\n.dsh-chatroom-presence-dot[data-online=\"true\"] { background: #20b26b; }\n\n.dsh-chatroom-peer-message {\n  width: 100%;\n}\n\n.dsh-chatroom-peer-message > * {\n  align-items: flex-start !important;\n  text-align: left;\n}\n\n.dsh-chatroom-peer-message > * > *:first-child,\n.dsh-chatroom-peer-message > * > *:first-child > * {\n  align-items: flex-start !important;\n  align-self: flex-start !important;\n}\n";
